+// Sales from the till: each sold dish uses its recipe's portions. Sales are
+// kept in `store.data.sales` as { ticket, soldAt, lines: [{ dishId, qty }] }.
+import { AppError } from "../errors.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when the ticket was already imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Stores a sale (one ticket with its dish lines). */
+export function addSale(store, sale) {
+  store.data.sales ??= [];
+  store.data.sales.push(sale);
+  return sale;
+}
+
+/** Theoretical use per item (3 decimals) from sales sold between two days (inclusive). */
+function theoreticalUse(store, from, to) {
+  const use = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const line of sale.lines) {
+      const recipe = getRecipe(store, getDish(store, line.dishId).recipeId);
+      for (const n of scaled(recipe, line.qty)) use.set(n.itemId, (use.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+  return use;
+}
+
+/** Per item: theoretical use from sales, actual use from `consume` movements, and the difference (actual - theoretical). */
+export function varianceReport(store, from, to) {
+  if (!from || !to) throw new AppError("invalid_date");
+  const theory = theoreticalUse(store, from, to);
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const ids = [...new Set([...theory.keys(), ...actual.keys()])].sort((a, b) => a - b);
+  return ids
+    .map((itemId) => {
+      const theoretical = round3(theory.get(itemId) ?? 0);
+      const act = round3(actual.get(itemId) ?? 0);
+      return { itemId, theoretical, actual: act, difference: round3(act - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
